function hasBatchim(str) {
  const s = String(str || '').trim().replace(/[.?!'"』》」)\]]+$/g, '');
  if (!s) return false;
  const ch = s[s.length - 1];
  const code = ch.charCodeAt(0);
  if (code >= 0xac00 && code <= 0xd7a3) {
    return (code - 0xac00) % 28 !== 0;
  }
  if (/[013678lmnrLMNR]/.test(ch)) return true;
  return false;
}

function josa(word, pair) {
  const [withB, withoutB] = pair.split('/');
  if (pair === '으로/로') {
    const s = String(word || '').trim().replace(/[.?!'"』》」)\]]+$/g, '');
    const ch = s[s.length - 1] || '';
    const code = ch.charCodeAt(0);
    if (code >= 0xac00 && code <= 0xd7a3) {
      const jong = (code - 0xac00) % 28;
      if (jong === 0 || jong === 8) return withoutB;
      return withB;
    }
    return hasBatchim(word) ? withB : withoutB;
  }
  return hasBatchim(word) ? withB : withoutB;
}

function decadeOf(year) {
  return `${Math.floor(year / 10) * 10}년대`;
}

function excludeValues(pool, forbidden) {
  const ban = forbidden instanceof Set ? forbidden : new Set(forbidden || []);
  return pool.filter((item) => !ban.has(item));
}

